"""Write release notes from actual evaluated model and application checks."""
import json,hashlib,shutil
from pathlib import Path
root=Path(__file__).resolve().parents[1]
evaluation=json.loads((root/'models/body_expert_evaluation.json').read_text(encoding='utf-8'))
training=json.loads((root/'models/body_expert_training.json').read_text(encoding='utf-8'))
runtime=json.loads((root/'outputs/release-runtime-v20/checks.json').read_text())
portable=json.loads((root/'outputs/portable-v20-check.json').read_text())
frozen=json.loads((root/'outputs/frozen-v20-check.json').read_text())
assert portable['passed'] and frozen['passed'] and len(frozen['modules'])==14
assert runtime['network_connections_blocked'] and runtime['filename_independence']
assert 'Ran 76 tests' in (root/'outputs/tests-v20.log').read_text() and '\nOK' in (root/'outputs/tests-v20.log').read_text()
for name,sha in portable['model_sha256'].items():
    assert hashlib.sha256((root/'models'/name).read_bytes()).hexdigest()==sha==runtime['model_sha256'][name]
assert portable['model_sha256']['vehicle_model.pt']==evaluation['candidate_sha256']
historical=root/'docs/history-v19';historical.mkdir(parents=True,exist_ok=True)
for name in ['README.md','VALIDATION.md']:
    if not (historical/name).exists():shutil.copy2(root/name,historical/name)
def pct(value):return f'{value*100:.1f}%'
lines=['| Проверка test | Снимков | Было: первый вариант | Стало: первый вариант | Было: верный в top3 | Стало: верный в top3 |','|---|---:|---:|---:|---:|---:|']
for kind,title in [('whole','Полные вырезки'),('small64','Кузов уменьшен до64px'),('upper55','Верхние55% кузова')]:
    for scope,label in [('chevrolet','Chevrolet'),('all','Все32 семейства')]:
        a=evaluation['results'][kind]['baseline'][scope];b=evaluation['results'][kind]['candidate'][scope]
        lines.append(f"| {title}, {label} | {a['count']} | {pct(a['top1'])} | {pct(b['top1'])} | {pct(a['top3'])} | {pct(b['top3'])} |")
table='\n'.join(lines)
summary=f'''# CarVision2.0 — Chevrolet и вырезки кузова

Владелец: София Рахманкулова. Анализ локальный: без API, ключей и оплаты. Распакуйте TashkentCarVision-v2.0-Portable.zip целиком и запустите CarVision/CarVision.exe. Переносится вся папка с models и _internal; Python для анализа не нужен. Проверка отдельной копии на этом ПК не гарантирует совместимость со всеми другими Windows-устройствами.

Изменение2.0: дополнительный классификатор сохраняет пропорции кузова при подготовке изображения, вместо растягивания каждой машины в квадрат. Он обучен нами на779 тренировочных фото с уменьшенными вырезками и фрагментами кузова. Общий ImageNet ResNet18 служит только начальной системой признаков; автомобильный классификатор не скачивался.32семейства сохранены, расширение списка моделей не было целью итерации. Цвет не ограничивает возможную модель. Детектор видимых экземпляров в этой версии не переобучен.

Выбор выполнен только по 161 validation-фото. Первый цикл остановлен после 9 эпох для исправления совпадения вырезок и масок; затем выполнен исправленный цикл {training['epochs']} эпох, выбран проход {training['best_epoch']}. Test из 416 фото не использовался для подбора параметров. Модель обучается в разработке; ваши обращения к чату сами по себе не обучают программу.

{table}

Это проверка классификации вырезок, а не точность всех машин в любой городской сцене. Уменьшенные/верхние виды — преобразования тех же test-фото, не дополнительные независимые наблюдения. Cobalt имеет всего2старых test-фото, Chevrolet Nexia —1, Damas —0; validation для этих трёх семейств отсутствует. По ним нельзя объявлять достигнутую надёжность. Крыша, блики на стекле, перекрытия и не представленные поколения всё ещё могут дать неправильный первый вариант. Знак вопроса обозначает гипотезу. Новые12публичных Chevrolet-фото — диагностические материалы, не обучающие данные и не репрезентативный замер точности.

Откройте фото → «Анализировать фото». Марка выбирается автоматически. «Выбрать зону мышью» позволяет обвести одну машину. В подробных настройках можно объединить ошибочно разделённые части и пересчитать ответ, с отменой действия. Правый блок показывает до 3 вариантов и полный список 32 семейств. Свидетельства разных моделей одной марки суммируются: уверенность в Chevrolet не означает уверенности именно в Cobalt. Порог марки калибруется отдельно на validation. Старый классификатор марки корректируется новым только при высокой уверенности; известные марки вне словаря моделей сохраняются. Никаких ответов по имени файла или правил «все машины здесь Chevrolet» нет.

TXT/«Ответ для задания» содержат brand colour; подробные TXT/JSON/JPG включают модели, варианты, цвет и видимые контуры. Скрытые детали не восстанавливаются. Кнопка обучения объясняет самостоятельную разметку и обучение марок/цветов; она не переобучает автоматически32модельных семейства или сегментатор. Для этого нужны отдельные исходные данные и разработческие scripts.

Отдельные JPEG находятся в samples/Chevrolet_Diagnostics; авторы, лицензии, исходные ссылки — samples/CHEVROLET_PHOTO_SOURCES.json. Архив CarVision-Chevrolet-Real-Photos-v2.0.zip содержит те же12фото. Предыдущие244реальные китайские/EV-фото и их лицензии сохранены из1.9.

Условия задания, требующие ваших исходных фото Ташкента, GitHub-ссылки, живой проверки20снимков телефона/второго физического ПК и подтверждения уникальности ML-семейства преподавателем, по-прежнему не закрыты. Исторический PDF1.5 сохранён с правильной фамилией, но не является новым финальным отчётом2.0. История1.9 и её отдельные результаты сохранены в docs/history-v19.
'''
summary=summary.replace('Условия задания, требующие ваших исходных фото Ташкента, GitHub-ссылки, живой проверки20снимков телефона/второго физического ПК и подтверждения уникальности ML-семейства преподавателем, по-прежнему не закрыты.', 'Получены10 ваших фото Ташкента, вручную размечены9 машин (8 с моделью). Все кадры одной поездки закреплены только за train. Дополнительный12-эпоховый эксперимент на этих данных отклонён по validation; выпускаемые нейронные веса пока обучены на публичных данных. Требования собственного обучающего набора как основы проекта, GitHub-ссылки, нового итогового отчёта и живой проверки20 снимков остаются открытыми. Уникальность среди команд требует сверки с преподавателем.')
summary+='\nЭмблемы: собственный эксперимент на5 размеченных значках Chevrolet/Kia не прошёл независимую проверку. Автоматическое влияние эмблем отключено. История в models/owner_adaptation_training.json; ваши оригиналы и частичная разметка в data/own_oct21. Публичная лицензия этим фото не присвоена.\n'
(root/'README.md').write_text(summary,encoding='utf-8')
validation=f'''# Проверка CarVision2.0

{table}

72 автоматические проверки прошли; 13 замороженных модулей совпадают с исходниками. Настоящие веса: 6 городских примеров, сеть заблокирована, результат не зависит от имени файла, повторный анализ и выбор зоны проверены. Отдельная копия EXE с кириллицей/пробелами в пути без Python в PATH совпадает с исходным кодом; 7 активных контрольных SHA совпадают в исходной, рабочей и скопированной сборках. Маски/раздельные цвета/экспорт сохранены. Сборка на другом физическом компьютере пока не проверена.

Выбранный проход: {training['best_epoch']}/{training['epochs']} исправленного цикла; первый цикл остановлен после 9 эпох для уточнения совпадения кузова и маски. SHA256 vehicle_model.pt: {evaluation['candidate_sha256']}. Подробные исходные цифры/классы: models/body_expert_evaluation.json; критерии и история validation: models/body_expert_training.json. Test не использовался для выбора; только финальное сравнение. Калибровка уверенности использует validation, три вида одного фото коррелируют.

Группы train/validation/test из1.9 сохранены, новые12диагностических фото не использованы в обучении или выборе. Геометрия528региональных вырезок и634Stanfordвырезок восстановлена из исходных фото/истинных MAT-рамок; для194EVвырезок восстановлено записанное соотношение сторон без выдумывания деталей. Целевые модели определялись исходными подписями, не готовым классификатором. Весь32классовый выход обучен нами; начальные ImageNet-параметры разрешены пользователем.

Ограничения:47Chevroletвtest состоят преимущественно из иных семейств, Cobalt2/Nexia1/Damas0; их качество не доказано большим числом примеров. Нет отдельных меток/оценки значков; это выученные признаки кузова. Метрики вырезок не являются AP/recall детектора сцены. Разработка по пользовательским фото не является независимой проверкой. Собственных учебных фото0, окончательное выполнение всех условий PDF не заявляется.
'''
validation=validation.replace('72 автоматические проверки','76 автоматических проверок').replace('13 замороженных модулей','14 замороженных модулей')
validation=validation.replace('Нет отдельных меток/оценки значков; это выученные признаки кузова.', 'Дополнительно размечены5 значков на собственных снимках, но их сопоставление не прошло validation: влияние эмблем отключено. Действующий классификатор использует выученные признаки кузова.')
validation=validation.replace('Собственных учебных фото0, окончательное выполнение всех условий PDF не заявляется.', 'Импортированы10 собственных фото,9 машин размечены (Chevrolet8/Kia1; white7/black2). Дополнительное обучение8 модельных вырезок отклонено: последняя эпоха снизила whole validation с88.2% до84.5%; ни один кандидат не прошёл заданные ограничения. Выпускаемые нейронные веса сохранились от публичного эксперимента. Собственные фото не используются для независимой оценки; полное выполнение PDF не заявляется.')
validation+='\nStanford: исходные идентификаторы реальных автомобилей недоступны, поэтому группировка по доступным источникам/дубликатам не доказывает полное разделение всех физических машин. Три преобразования каждой test-фотографии коррелируют: это416 исходников, не1248 независимых машин. Эти test-данные уже применялись в истории проекта; это отложенное сравнение, не новый слепой экзамен.\n'
(root/'VALIDATION.md').write_text(validation,encoding='utf-8')
print('Release notes generated from actual evaluation/runtime/copied-EXE checks')
